select throws_ok($$select public.product_command('commercial.membership.freeze',jsonb_build_object('id',current_setting('test.commercial_member'),'frozen',false,'reason','Attempt to resume cancelled member'),gen_random_uuid())$$,'P0409',null,'Cancelled membership cannot be resumed');
select throws_ok($$select public.product_command('commercial.membership.renew',jsonb_build_object('id',current_setting('test.commercial_member'),'accepted',true),gen_random_uuid())$$,'P0409',null,'Cancelled membership cannot be renewed');
reset role;
select is(private.commercial_due(current_setting('test.commercial_invoice')::uuid),0::bigint,'Final invoice credit and retained allocation reconcile to zero debt');
select lives_ok($$select private.commercial_sync_membership(current_setting('test.commercial_invoice')::uuid)$$,'Later accounting synchronization retains terminal cancellation');
select is((select status from public.commercial_memberships where id=current_setting('test.commercial_member')::uuid),'cancelled','Paid cancellation never reactivates through synchronization');
select throws_ok($$update public.commercial_cancellation_previews set state_hash='changed'$$,'42501',null,'Persisted cancellation previews are immutable');
select throws_ok($$delete from public.commercial_membership_cancellations$$,'42501',null,'Cancellation records are immutable');

